def _abd(dist, where, lateral):
    if dist == 0:
        return f"On the abdomen, {lateral} B-cun lateral to the centre of the umbilicus."
    part = "upper" if where == "superior" else "lower"
    return f"On the {part} abdomen, {dist} B-cun {where} to the centre of the umbilicus, {lateral} B-cun lateral to the anterior median line."

